using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchPdf.Infrastructure.Services
{
    /// <summary>
    /// Losslessly combines multiple single-page PDF files generated by AutoCAD's PlotEngine + "DWG To PDF.pc3"
    /// into a single multi-page PDF document in exact task order, preserving each page's physical MediaBox
    /// (mixed paper sizes A0-A4, portrait/landscape, and custom/lengthened sizes), vector streams, fonts, and OCG layers.
    /// Uses zero external third-party libraries.
    /// </summary>
    public class PdfPageCombiner
    {
        private static readonly Encoding Latin1 = Encoding.GetEncoding("iso-8859-1");

        private static readonly Regex ObjHeaderRegex = new Regex(
            @"(?:^|\r|\n)\s*(\d+)\s+0\s+obj\b",
            RegexOptions.Compiled);

        private static readonly Regex IndirectRefRegex = new Regex(
            @"(?<!\d)(\d+)\s+0\s+R\b",
            RegexOptions.Compiled);

        private static readonly Regex TypePageRegex = new Regex(
            @"/Type\s*/Page\b(?!s)",
            RegexOptions.Compiled);

        private static readonly Regex TypePagesRegex = new Regex(
            @"/Type\s*/Pages\b",
            RegexOptions.Compiled);

        private static readonly Regex TypeCatalogRegex = new Regex(
            @"/Type\s*/Catalog\b",
            RegexOptions.Compiled);

        private static readonly Regex TypeOcgRegex = new Regex(
            @"/Type\s*/OCG\b",
            RegexOptions.Compiled);

        private class ParsedPdfObject
        {
            public int NewObjectId { get; set; }
            public string RewrittenHeader { get; set; }
            public string RawStreamBlock { get; set; }
            public bool IsPageObject { get; set; }
        }

        /// <summary>
        /// Combines multiple single-page PDF files into a single multi-page PDF document.
        /// </summary>
        public void CombineSinglePagePdfs(IList<string> sourcePdfPaths, string outputPdfPath)
        {
            CombineSinglePagePdfs(sourcePdfPaths, outputPdfPath, null);
        }

        /// <summary>
        /// Losslessly combines multiple single-page PDF files generated by AutoCAD's PlotEngine + "DWG To PDF.pc3"
        /// into a single multi-page PDF document in exact task order, preserving each page's physical MediaBox
        /// (mixed paper sizes A0-A4, portrait/landscape, and custom/lengthened sizes), vector streams, fonts, and OCG layers.
        /// When <paramref name="sheetBookmarks"/> is provided, generates native PDF outline bookmark tree
        /// (/Outlines, /First, /Last, /Count, /Title, /Parent, /Dest) and configures /Catalog with /PageMode /UseOutlines
        /// so that PDF viewers automatically expand the bookmark hierarchy on open.
        /// Uses zero external third-party libraries.
        /// </summary>
        /// <param name="sourcePdfPaths">List of file paths to single-page PDFs.</param>
        /// <param name="outputPdfPath">Target file path for the merged multi-page PDF.</param>
        /// <param name="sheetBookmarks">Optional list of bookmark titles corresponding to each sheet.</param>
        public void CombineSinglePagePdfs(
            IList<string> sourcePdfPaths,
            string outputPdfPath,
            IList<string> sheetBookmarks = null)
        {
            if (sourcePdfPaths == null || sourcePdfPaths.Count == 0)
            {
                throw new ArgumentException("没有可合并的源 PDF 文件。", nameof(sourcePdfPaths));
            }

            if (sourcePdfPaths.Count == 1 && (sheetBookmarks == null || sheetBookmarks.Count == 0))
            {
                if (!string.Equals(Path.GetFullPath(sourcePdfPaths[0]), Path.GetFullPath(outputPdfPath), StringComparison.OrdinalIgnoreCase))
                {
                    File.Copy(sourcePdfPaths[0], outputPdfPath, overwrite: true);
                }
                return;
            }

            var allOutputObjects = new List<ParsedPdfObject>();
            var pageObjectIds = new List<int>();
            var ocgObjectIds = new List<int>();

            int currentIdOffset = 0;
            const int MasterPagesPlaceholder = -999999;

            foreach (string srcPath in sourcePdfPaths)
            {
                if (!File.Exists(srcPath))
                {
                    throw new FileNotFoundException("找不到待合并的单页 PDF 文件: " + srcPath, srcPath);
                }

                byte[] rawBytes = File.ReadAllBytes(srcPath);
                string rawContent = Latin1.GetString(rawBytes);

                List<Tuple<int, string, string>> rawObjects = ExtractObjectsFromPdf(rawContent);
                if (rawObjects.Count == 0)
                {
                    throw new InvalidDataException("无法解析 PDF 对象结构: " + srcPath);
                }

                int maxOldId = rawObjects.Max(o => o.Item1);
                int oldPagesId = -1;
                int oldCatalogId = -1;
                int oldInfoId = -1;

                // Identify old /Pages, /Catalog, and trailer /Info
                Match trailerInfoMatch = Regex.Match(rawContent, @"/Info\s+(\d+)\s+0\s+R\b");
                if (trailerInfoMatch.Success)
                {
                    int.TryParse(trailerInfoMatch.Groups[1].Value, out oldInfoId);
                }

                var outlineIdsToSkip = new HashSet<int>();

                foreach (var obj in rawObjects)
                {
                    int oldId = obj.Item1;
                    string hdr = obj.Item2;
                    if (TypePagesRegex.IsMatch(hdr))
                    {
                        oldPagesId = oldId;
                    }
                    else if (TypeCatalogRegex.IsMatch(hdr))
                    {
                        oldCatalogId = oldId;
                        Match outMatch = Regex.Match(hdr, @"/Outlines\s+(\d+)\s+0\s+R\b");
                        if (outMatch.Success && int.TryParse(outMatch.Groups[1].Value, out int outRootId))
                        {
                            outlineIdsToSkip.Add(outRootId);
                        }
                    }
                }

                // Also skip outline hierarchy objects (which contain /Dest [...] and /Parent or /Type /Outlines)
                foreach (var obj in rawObjects)
                {
                    if (Regex.IsMatch(obj.Item2, @"/Type\s*/Outlines\b") ||
                        Regex.IsMatch(obj.Item2, @"/Dest\s*\["))
                    {
                        outlineIdsToSkip.Add(obj.Item1);
                    }
                }

                bool foundPageInFile = false;

                foreach (var obj in rawObjects)
                {
                    int oldId = obj.Item1;
                    string headerPart = obj.Item2;
                    string streamBlock = obj.Item3;

                    if (oldId == oldPagesId || oldId == oldCatalogId || oldId == oldInfoId || outlineIdsToSkip.Contains(oldId))
                    {
                        continue;
                    }

                    int newId = currentIdOffset + oldId;
                    bool isPage = TypePageRegex.IsMatch(headerPart);
                    bool isOcg = TypeOcgRegex.IsMatch(headerPart);

                    string rewrittenHeader = IndirectRefRegex.Replace(headerPart, m =>
                    {
                        int refOldId = int.Parse(m.Groups[1].Value, CultureInfo.InvariantCulture);
                        if (refOldId == oldPagesId)
                        {
                            return MasterPagesPlaceholder.ToString(CultureInfo.InvariantCulture) + " 0 R";
                        }
                        int refNewId = currentIdOffset + refOldId;
                        return refNewId.ToString(CultureInfo.InvariantCulture) + " 0 R";
                    });

                    if (isPage && !foundPageInFile)
                    {
                        foundPageInFile = true;
                        pageObjectIds.Add(newId);
                    }

                    if (isOcg)
                    {
                        ocgObjectIds.Add(newId);
                    }

                    allOutputObjects.Add(new ParsedPdfObject
                    {
                        NewObjectId = newId,
                        RewrittenHeader = rewrittenHeader,
                        RawStreamBlock = streamBlock,
                        IsPageObject = isPage
                    });
                }

                currentIdOffset += maxOldId + 2;
            }

            if (pageObjectIds.Count == 0)
            {
                throw new InvalidOperationException("合并 PDF 失败：未能从源文件中提取到任何有效页面对象。");
            }

            int nextId = currentIdOffset + 1;
            int masterPagesId = nextId++;
            int masterCatalogId = nextId++;
            int masterInfoId = nextId++;

            int masterOutlineRootId = 0;
            var outlineItemIds = new List<int>();

            bool hasBookmarks = sheetBookmarks != null && sheetBookmarks.Count > 0 && pageObjectIds.Count > 0;
            if (hasBookmarks)
            {
                masterOutlineRootId = nextId++;
                int count = Math.Min(sheetBookmarks.Count, pageObjectIds.Count);
                for (int i = 0; i < count; i++)
                {
                    outlineItemIds.Add(nextId++);
                }
            }

            int totalXrefSize = nextId;

            string placeholderToken = MasterPagesPlaceholder.ToString(CultureInfo.InvariantCulture) + " 0 R";
            string actualMasterPagesRef = masterPagesId.ToString(CultureInfo.InvariantCulture) + " 0 R";

            foreach (var obj in allOutputObjects)
            {
                if (obj.RewrittenHeader.Contains(placeholderToken))
                {
                    obj.RewrittenHeader = obj.RewrittenHeader.Replace(placeholderToken, actualMasterPagesRef);
                }
            }

            // Add Master /Pages object
            string kidsRefs = string.Join(" ", pageObjectIds.Select(id => id.ToString(CultureInfo.InvariantCulture) + " 0 R"));
            allOutputObjects.Add(new ParsedPdfObject
            {
                NewObjectId = masterPagesId,
                RewrittenHeader = string.Format(
                    CultureInfo.InvariantCulture,
                    "<< /Type /Pages /Kids [ {0} ] /Count {1} >>",
                    kidsRefs,
                    pageObjectIds.Count),
                RawStreamBlock = null
            });

            // Add Master /Catalog object
            string ocgProps = "";
            if (ocgObjectIds.Count > 0)
            {
                string ocgRefs = string.Join(" ", ocgObjectIds.Select(id => id.ToString(CultureInfo.InvariantCulture) + " 0 R"));
                ocgProps = string.Format(
                    CultureInfo.InvariantCulture,
                    " /OCProperties << /OCGs [ {0} ] /D << /Order [ {0} ] /OFF [] >> >>",
                    ocgRefs);
            }

            string outlinesRef = "";
            string pageMode = "";
            if (hasBookmarks && outlineItemIds.Count > 0)
            {
                outlinesRef = string.Format(CultureInfo.InvariantCulture, " /Outlines {0} 0 R", masterOutlineRootId);
                pageMode = " /PageMode /UseOutlines";
            }
            else if (ocgObjectIds.Count > 0)
            {
                pageMode = " /PageMode /UseOC";
            }

            allOutputObjects.Add(new ParsedPdfObject
            {
                NewObjectId = masterCatalogId,
                RewrittenHeader = string.Format(
                    CultureInfo.InvariantCulture,
                    "<< /Type /Catalog /Pages {0} 0 R{1}{2}{3} /PageLayout /SinglePage >>",
                    masterPagesId,
                    outlinesRef,
                    pageMode,
                    ocgProps),
                RawStreamBlock = null
            });

            // Add Master /Info object
            string nowStr = DateTime.Now.ToString("yyyyMMddHHmmss", CultureInfo.InvariantCulture);
            allOutputObjects.Add(new ParsedPdfObject
            {
                NewObjectId = masterInfoId,
                RewrittenHeader = string.Format(
                    CultureInfo.InvariantCulture,
                    "<< /Producer (AutoCAD DWG To PDF.pc3 / BatchPdf) /CreationDate (D:{0}) /ModDate (D:{0}) >>",
                    nowStr),
                RawStreamBlock = null
            });

            // Add Master /Outlines Root object and Items
            if (hasBookmarks && outlineItemIds.Count > 0)
            {
                int firstId = outlineItemIds[0];
                int lastId = outlineItemIds[outlineItemIds.Count - 1];
                int count = outlineItemIds.Count;

                allOutputObjects.Add(new ParsedPdfObject
                {
                    NewObjectId = masterOutlineRootId,
                    RewrittenHeader = string.Format(
                        CultureInfo.InvariantCulture,
                        "<< /Type /Outlines /First {0} 0 R /Last {1} 0 R /Count {2} >>",
                        firstId,
                        lastId,
                        count),
                    RawStreamBlock = null
                });

                for (int i = 0; i < outlineItemIds.Count; i++)
                {
                    int itemId = outlineItemIds[i];
                    int targetPageId = pageObjectIds[i];
                    string rawTitle = sheetBookmarks[i];
                    if (string.IsNullOrWhiteSpace(rawTitle))
                    {
                        rawTitle = string.Format(CultureInfo.InvariantCulture, "第 {0} 页", i + 1);
                    }
                    string encodedTitle = EncodePdfTextString(rawTitle);

                    var itemHdr = new StringBuilder();
                    itemHdr.Append("<< ");
                    itemHdr.AppendFormat(CultureInfo.InvariantCulture, "/Title {0} ", encodedTitle);
                    itemHdr.AppendFormat(CultureInfo.InvariantCulture, "/Parent {0} 0 R ", masterOutlineRootId);

                    if (i > 0)
                    {
                        itemHdr.AppendFormat(CultureInfo.InvariantCulture, "/Prev {0} 0 R ", outlineItemIds[i - 1]);
                    }
                    if (i < outlineItemIds.Count - 1)
                    {
                        itemHdr.AppendFormat(CultureInfo.InvariantCulture, "/Next {0} 0 R ", outlineItemIds[i + 1]);
                    }

                    itemHdr.AppendFormat(CultureInfo.InvariantCulture, "/Dest [ {0} 0 R /XYZ null null null ] ", targetPageId);
                    itemHdr.Append(">>");

                    allOutputObjects.Add(new ParsedPdfObject
                    {
                        NewObjectId = itemId,
                        RewrittenHeader = itemHdr.ToString(),
                        RawStreamBlock = null
                    });
                }
            }

            // Write combined PDF bytes with exact xref byte offsets
            using (var ms = new MemoryStream())
            {
                void WriteLatin1(string s)
                {
                    byte[] b = Latin1.GetBytes(s);
                    ms.Write(b, 0, b.Length);
                }

                WriteLatin1("%PDF-1.7\r\n%\xE2\xE3\xCF\xD3\r\n");

                var offsetsById = new Dictionary<int, long>();
                foreach (var obj in allOutputObjects.OrderBy(o => o.NewObjectId))
                {
                    offsetsById[obj.NewObjectId] = ms.Position;
                    WriteLatin1(string.Format(CultureInfo.InvariantCulture, "{0} 0 obj\r\n", obj.NewObjectId));
                    WriteLatin1(obj.RewrittenHeader.Trim());
                    WriteLatin1("\r\n");
                    if (!string.IsNullOrEmpty(obj.RawStreamBlock))
                    {
                        WriteLatin1(obj.RawStreamBlock);
                        if (!obj.RawStreamBlock.EndsWith("\n"))
                        {
                            WriteLatin1("\r\n");
                        }
                    }
                    WriteLatin1("endobj\r\n");
                }

                long startXrefOffset = ms.Position;
                WriteLatin1(string.Format(CultureInfo.InvariantCulture, "xref\r\n0 {0}\r\n", totalXrefSize));
                WriteLatin1("0000000000 65535 f \r\n");

                for (int id = 1; id < totalXrefSize; id++)
                {
                    if (offsetsById.TryGetValue(id, out long pos))
                    {
                        WriteLatin1(string.Format(CultureInfo.InvariantCulture, "{0:D10} 00000 n \r\n", pos));
                    }
                    else
                    {
                        WriteLatin1("0000000000 65535 f \r\n");
                    }
                }

                WriteLatin1(string.Format(
                    CultureInfo.InvariantCulture,
                    "trailer\r\n<< /Size {0} /Root {1} 0 R /Info {2} 0 R >>\r\nstartxref\r\n{3}\r\n%%EOF\r\n",
                    totalXrefSize,
                    masterCatalogId,
                    masterInfoId,
                    startXrefOffset));

                File.WriteAllBytes(outputPdfPath, ms.ToArray());
            }
        }

        private static List<Tuple<int, string, string>> ExtractObjectsFromPdf(string rawContent)
        {
            var results = new List<Tuple<int, string, string>>();

            // Find xref start so we don't scan past xref
            int xrefPos = rawContent.LastIndexOf("\nxref", StringComparison.Ordinal);
            if (xrefPos < 0) xrefPos = rawContent.LastIndexOf("\rxref", StringComparison.Ordinal);
            if (xrefPos < 0) xrefPos = rawContent.Length;

            int searchPos = 0;
            while (searchPos < xrefPos)
            {
                Match m = ObjHeaderRegex.Match(rawContent, searchPos);
                if (!m.Success || m.Index >= xrefPos)
                {
                    break;
                }

                int objId = int.Parse(m.Groups[1].Value, CultureInfo.InvariantCulture);
                int bodyStart = m.Index + m.Length;

                // Check if there is a "stream" keyword before the next "endobj"
                int nextEndObj = rawContent.IndexOf("endobj", bodyStart, StringComparison.Ordinal);
                if (nextEndObj < 0) break;

                int streamIdx = FindStreamKeywordOutsideInner(rawContent, bodyStart, nextEndObj);
                if (streamIdx >= 0)
                {
                    string headerPart = rawContent.Substring(bodyStart, streamIdx - bodyStart);

                    // Find "endstream" after streamIdx; use /Length if available to jump past binary stream data safely
                    int streamDataStart = streamIdx + "stream".Length;
                    if (streamDataStart < rawContent.Length && rawContent[streamDataStart] == '\r') streamDataStart++;
                    if (streamDataStart < rawContent.Length && rawContent[streamDataStart] == '\n') streamDataStart++;

                    int endStreamSearchStart = streamDataStart;
                    Match lenMatch = Regex.Match(headerPart, @"/Length\s+(\d+)(?!\s+0\s+R)");
                    if (lenMatch.Success && int.TryParse(lenMatch.Groups[1].Value, out int declaredLen) && declaredLen > 0)
                    {
                        endStreamSearchStart = Math.Min(rawContent.Length, streamDataStart + declaredLen);
                    }

                    int endStreamIdx = rawContent.IndexOf("endstream", endStreamSearchStart, StringComparison.Ordinal);
                    if (endStreamIdx < 0)
                    {
                        endStreamIdx = rawContent.IndexOf("endstream", streamDataStart, StringComparison.Ordinal);
                    }
                    if (endStreamIdx < 0) break;

                    int endStreamEnd = endStreamIdx + "endstream".Length;
                    string rawStreamBlock = rawContent.Substring(streamIdx, endStreamEnd - streamIdx);

                    int realEndObj = rawContent.IndexOf("endobj", endStreamEnd, StringComparison.Ordinal);
                    if (realEndObj < 0) break;

                    results.Add(Tuple.Create(objId, headerPart, rawStreamBlock));
                    searchPos = realEndObj + "endobj".Length;
                }
                else
                {
                    string headerPart = rawContent.Substring(bodyStart, nextEndObj - bodyStart);
                    results.Add(Tuple.Create(objId, headerPart, (string)null));
                    searchPos = nextEndObj + "endobj".Length;
                }
            }

            return results;
        }

        private static int FindStreamKeywordOutsideInner(string content, int start, int limit)
        {
            int idx = start;
            while (idx < limit)
            {
                int pos = content.IndexOf("stream", idx, limit - idx, StringComparison.Ordinal);
                if (pos < 0) return -1;

                // Ensure it is "stream" and not "endstream"
                bool precededByEnd = pos >= 3 && content.Substring(pos - 3, 3) == "end";
                int after = pos + 6;
                bool followedByNewline = after < content.Length && (content[after] == '\r' || content[after] == '\n');

                if (!precededByEnd && followedByNewline)
                {
                    return pos;
                }
                idx = pos + 6;
            }
            return -1;
        }

        /// <summary>
        /// Encodes a text string for PDF according to the PDF 1.7 specification.
        /// Plain ASCII strings without parentheses or backslashes are formatted as literal strings `(...)`.
        /// Strings with non-ASCII characters (e.g. Chinese characters) or special characters are encoded
        /// in UTF-16BE hexadecimal format with BOM 0xFE, 0xFF: &lt;FEFF...&gt;.
        /// </summary>
        public static string EncodePdfTextString(string text)
        {
            if (string.IsNullOrEmpty(text))
            {
                return "()";
            }

            bool isSafeAscii = true;
            for (int i = 0; i < text.Length; i++)
            {
                char c = text[i];
                if (c < 32 || c > 126 || c == '(' || c == ')' || c == '\\')
                {
                    isSafeAscii = false;
                    break;
                }
            }

            if (isSafeAscii)
            {
                return "(" + text + ")";
            }

            byte[] utf16BeBytes = Encoding.BigEndianUnicode.GetBytes(text);
            var sb = new StringBuilder(utf16BeBytes.Length * 2 + 8);
            sb.Append("<FEFF");
            for (int i = 0; i < utf16BeBytes.Length; i++)
            {
                sb.Append(utf16BeBytes[i].ToString("X2", CultureInfo.InvariantCulture));
            }
            sb.Append(">");
            return sb.ToString();
        }
    }
}
